def run_cmd(
    cmd: list[str],
    *,
    cwd: str | Path | None = None,
    timeout: int | None = None,
    check: bool = False,
) -> subprocess.CompletedProcess[str]:
    """Run a subprocess with UTF-8 encoding and replacement for decode errors.

    All subprocess calls in this project should use this wrapper to avoid
    UnicodeDecodeError on Windows (cp1252 default can't handle all output).
    """
    return subprocess.run(
        cmd,
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        cwd=cwd,
        timeout=timeout,
        check=check,
    )


def format_event_time(time_str: str) -> str:
    """Format ISO datetime string to HH:MM.

    Returns empty string for date-only or missing values.
    """
    if not time_str or len(time_str) <= 10:
        return ""
    try:
        return datetime.fromisoformat(time_str).strftime("%H:%M")
    except ValueError:
        return time_str[:5]


def _atomic_write(path: Path, writer: Callable[[IO[str]], Any]) -> None:
    """Write a file atomically using a temp file + os.replace()."""
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temp_path = tempfile.mkstemp(
        dir=path.parent,
        prefix=f".{path.name}.",
        suffix=".tmp",
    )
    try:
        with os.fdopen(fd, "w") as f:
            writer(f)
        os.replace(temp_path, path)
    except Exception:
        try:
            os.unlink(temp_path)
        except OSError:
            pass
        raise


def atomic_write_json(path: Path, data: Any, **json_kwargs: Any) -> None:
    """Write JSON data atomically. Prevents corruption if killed mid-write."""
    _atomic_write(path, lambda f: json.dump(data, f, **json_kwargs))


def atomic_write_text(path: Path, content: str) -> None:
    """Write text atomically. Prevents corruption if killed mid-write."""
    _atomic_write(path, lambda f: f.write(content))


_MEETING_URL_PATTERN = re.compile(
    r"https?://(?:meet\.google\.com/[a-z-]+"
    r"|teams\.microsoft\.com/l/meetup-join/[^\s\"]+"
    r"|[\w.]*zoom\.us/j/\d+[^\s\"]*)",
    re.IGNORECASE,
)


def get_meeting_url(event: CalendarEvent) -> str | None:
    """Extract a video conference URL from a calendar event.

    Checks hangout_link first, then falls back to regex-matching
    Meet/Teams/Zoom URLs in location and description fields.
    """
    hangout = event.get("hangout_link")
    if hangout:
        return hangout
    for field in ("location", "description"):
        text = event.get(field, "")
        if isinstance(text, str) and text:
            match = _MEETING_URL_PATTERN.search(text)
            if match:
                return match.group(0)
    return None


# Workspace hangs its own artifacts off the invite alongside the agenda, and
# people rarely clean up recurring events, so stale ones accumulate. Matching
# is on the title only -- attachments carry nothing else. Recordings need no
# marker: they are Drive files, not Docs, so the URL check already drops them.
# Transcripts need none either -- Gemini writes the transcript and the notes
# into one document, so "notes by gemini" is the whole exclusion list.
# Markers are only ever tested against titles that already say "notes", which
# is why "chat" and a bare "gemini" are deliberately absent -- both would cost
# a real agenda ("Chat notes", a doc named for a Gemini project) to catch an
# artifact that an extra browser tab would have made obvious anyway.
# ponytail: best effort, add a marker here when a new artifact shows up.
_NOT_AGENDA_MARKERS = ("notes by gemini",)

_GDOC_URL_PATTERN = re.compile(r"https://docs\.google\.com/document/[^\s\"'<>]+")

_ANCHOR_PATTERN = re.compile(
    r'<a\s+[^>]*href="([^"]*)"[^>]*>(.*?)</a>',
    re.IGNORECASE | re.DOTALL,
)


def _link_text(html: str) -> str:
    """Strip tags and unescape entities from an anchor's inner HTML."""
    return unescape(re.sub(r"<[^>]+>", "", html)).strip()


def get_notes_doc_urls(event: CalendarEvent) -> list[str]:
    """Return Google Docs URLs for agenda/notes docs linked from an invite.

    Looks at attachments and at links in the description, keeps Google Docs
    whose title says "notes", and drops the Gemini notes, transcripts and
    recordings that ride along on the same event. Order is preserved and
    duplicates removed.
    """
    candidates: list[tuple[str, str]] = [
        (att.get("title", ""), att.get("url", ""))
        for att in event.get("attachments", [])
    ]
    description = event.get("description", "") or ""
    candidates += [
        (_link_text(label), unescape(url))
        for url, label in _ANCHOR_PATTERN.findall(description)
    ]

    urls: list[str] = []
    for title, url in candidates:
        if not _GDOC_URL_PATTERN.match(url):
            continue
        name = title.lower()
        if "notes" not in name:
            continue
        if any(marker in name for marker in _NOT_AGENDA_MARKERS):
            continue
        if url not in urls:
            urls.append(url)
    return urls


# ponytail: session-level cache, refreshed on app restart
_gdoc_tab_cache: dict[str, dict[str, str]] = {}


def get_gdoc_tab_url(doc_id: str, tab_name: str) -> str | None:
    """Return a direct Google Docs URL for a tab matching tab_name."""
    from personal_assistant_dashboard.config import GWS_BINARY

    if doc_id not in _gdoc_tab_cache:
        try:
            result = run_cmd(
                [
                    GWS_BINARY,
                    "docs",
                    "documents",
                    "get",
                    "--params",
                    json.dumps({"documentId": doc_id, "includeTabsContent": True}),
                ],
                timeout=15,
            )
            if result.returncode == 0:
                doc = json.loads(result.stdout)
                tabs: dict[str, str] = {}

                def _collect(tab_list: list[dict[str, Any]]) -> None:
                    for tab in tab_list:
                        props = tab.get("tabProperties", {})
                        title = props.get("title", "")
                        tab_id = props.get("tabId", "")
                        if title and tab_id:
                            tabs[title.lower()] = tab_id
                        _collect(tab.get("childTabs", []))

                _collect(doc.get("tabs", []))
                _gdoc_tab_cache[doc_id] = tabs
            else:
                _logger.warning("gws docs get failed: %s", result.stderr[:200])
                return None
        except (OSError, json.JSONDecodeError) as exc:
            _logger.warning("Tab lookup failed: %s", exc)
            return None

    tab_id = _gdoc_tab_cache.get(doc_id, {}).get(tab_name.lower())
    if tab_id:
        return f"https://docs.google.com/document/d/{doc_id}/edit?tab={tab_id}"
    return None


_directory_name_cache: dict[str, str | None] = {}


def resolve_display_name(email: str) -> str | None:
    """Resolve an email to a display name via the People directory API."""
    from personal_assistant_dashboard.config import GWS_BINARY

    if email in _directory_name_cache:
        return _directory_name_cache[email]

    try:
        result = run_cmd(
            [
                GWS_BINARY,
                "people",
                "people",
                "searchDirectoryPeople",
                "--params",
                json.dumps(
                    {
                        "query": email,
                        "readMask": "names,emailAddresses",
                        "sources": "DIRECTORY_SOURCE_TYPE_DOMAIN_PROFILE",
                    }
                ),
            ],
            timeout=10,
        )
        if result.returncode == 0:
            data = json.loads(result.stdout)
            for person in data.get("people", []):
                emails = [
                    e.get("value", "").lower() for e in person.get("emailAddresses", [])
                ]
                if email.lower() in emails:
                    name: str | None = person.get("names", [{}])[0].get("displayName")
                    _directory_name_cache[email] = name
                    return name
    except (OSError, json.JSONDecodeError) as exc:
        _logger.warning("Directory lookup failed: %s", exc)

    _directory_name_cache[email] = None
    return None


def filter_dismissed_missed_meetings(
    missed_meetings: list[CalendarEvent],
    dismissed_ids: set[str],
) -> list[CalendarEvent]:
    """Remove dismissed-conflict events from a missed-meetings list."""
    if not dismissed_ids or not missed_meetings:
        return missed_meetings
    return [e for e in missed_meetings if e.get("id", "") not in dismissed_ids]


_FRONTMATTER_RE = re.compile(r"^---\n(.*?)\n---\n", re.DOTALL)


def _first_sentence(text: str, max_len: int = 120) -> str:
    """Return the first sentence of text, flattened and truncated to max_len."""
    normalized = " ".join(text.split())
    if not normalized:
        return ""
    match = re.search(r"[.!?](?:\s|$)", normalized)
    first = normalized[: match.end()].strip() if match else normalized
    if len(first) > max_len:
        first = first[: max_len - 3].rstrip() + "..."
    return first


def list_local_skills(skills_dir: Path) -> list[tuple[str, str]]:
    """Return (name, first-sentence description) pairs for all SKILL.md files.

    Parses YAML frontmatter from each ``SKILL.md`` under ``skills_dir``. Skips
    files with missing/invalid frontmatter or without a name+description pair.
    Returns an empty list if ``skills_dir`` does not exist.
    """
    if not skills_dir.is_dir():
        return []
    results: list[tuple[str, str]] = []
    for skill_md in sorted(skills_dir.glob("*/SKILL.md")):
        try:
            content = skill_md.read_text(encoding="utf-8")
        except OSError:
            continue
        match = _FRONTMATTER_RE.match(content)
        if not match:
            continue
        try:
            data = yaml.safe_load(match.group(1))
        except yaml.YAMLError:
            continue
        if not isinstance(data, dict):
            continue
        name = str(data.get("name", "") or "").strip()
        desc = str(data.get("description", "") or "").strip()
        if not name or not desc:
            continue
        results.append((name, _first_sentence(desc)))
    return results
